#!/bin/bash
set -euo pipefail
cd "$(dirname "$0")/.."
build_root="${1:?build output directory required}"
petlink_arch="${2:-arm64}"
case "$petlink_arch" in arm64|x86_64) ;; *) echo "Unsupported architecture" >&2; exit 1 ;; esac
mkdir -p "$build_root"
swiftc -parse-as-library -swift-version 5 -O -target ${petlink_arch}-apple-macosx13.0 client/AgentEventCLI.swift -o "$build_root/PetLinkAgentEvent"
swiftc -swift-version 5 -O -target ${petlink_arch}-apple-macosx13.0 -framework AppKit -framework SwiftUI -framework Security -framework CryptoKit -framework Network -framework AuthenticationServices client/Localization.swift client/ConversationActivity.swift client/CodexConversationCore.swift client/CodexSessionDiscovery.swift client/ClaudeSessionStatus.swift client/AvatarAgentAdapters.swift client/ClaudeConversationCore.swift client/ClaudeCoworkSessionDiscovery.swift client/DSHDesktopApplication.swift client/DSHDesktopSessionDiscovery.swift client/CodexConversationView.swift client/LocalCompanion.swift client/AgentSessionRegistry.swift client/ServiceEndpoint.swift client/GoogleAuthCore.swift client/GoogleLoopback.swift client/GoogleAuthCoordinator.swift client/GoogleAuthTransport.swift client/GoogleAuthBrowser.swift client/GoogleAuthView.swift client/PencilCore.swift client/PencilUI.swift client/WindowChrome.swift client/LeaseGate.swift client/Models.swift client/PetWindowGeometry.swift client/VisitorChatBubble.swift client/PetWindows.swift client/PetQuickMenu.swift client/PetShowroom.swift client/V2Models.swift client/AgentIntegrationCore.swift client/CodexDaemonProbe.swift client/ClaudeHookSettings.swift client/AvatarCore.swift client/AvatarIdentityVault.swift client/AvatarAuthorization.swift client/AvatarChatState.swift client/AvatarChatInput.swift client/AvatarView.swift client/AgentVersionMonitor.swift client/AgentIntegration.swift client/LocalSessionPresentation.swift client/AvatarRequestState.swift client/V2ClientModel.swift client/PetInteractionUI.swift client/DesktopUI.swift client/App.swift -o "$build_root/PetLink"
